{"content":"from math import gcd


_ALPHABET_SIZE = 26


def _validate_key(a):
    if gcd(a, _ALPHABET_SIZE) != 1:
        raise ValueError("a and m must be coprime.")


def _transform(text, multiplier, offset):
    result = []
    for character in text:
        if "A" <= character <= "Z":
            character = character.lower()
        if "a" <= character <= "z":
            index = ord(character) - ord("a")
            result.append(chr((multiplier * index + offset) % _ALPHABET_SIZE + ord("a")))
        elif "0" <= character <= "9":
            result.append(character)
    return "".join(result)


def encode(plain_text, a, b):
    """Encrypt Roman letters and retain digits, grouping output by five."""
    _validate_key(a)
    encrypted = _transform(plain_text, a, b)
    return " ".join(encrypted[index:index + 5] for index in range(0, len(encrypted), 5))


def decode(ciphered_text, a, b):
    """Decrypt to ungrouped lowercase text, retaining digits."""
    _validate_key(a)
    inverse = pow(a, -1, _ALPHABET_SIZE)
    return _transform(ciphered_text, inverse, -inverse * b)
